  "seoul-newlywed-loan-interest": {
    title: "การสนับสนุนดอกเบี้ยเงินประกันการเช่าสำหรับคู่สมรสใหม่กรุงโซล",
    summary: "โครงการสนับสนุนดอกเบี้ยเงินกู้เช่าจอนเซ (전세) สำหรับคู่สมรสใหม่หรือคู่ที่กำลังจะแต่งงานซึ่งอาศัยอยู่ในกรุงโซล",
    eligibility:
      "ต้องเป็นคู่สมรสใหม่ (หรือคู่ที่จะแต่งงานภายใน 6 เดือน) ที่จดทะเบียนสมรสมาไม่เกิน 7 ปี นับจากวันที่ยื่นขอสินเชื่อ มีรายได้รวมของทั้งคู่ต่อปีไม่เกิน 130,000,000 วอน และทั้งตนเองและคู่สมรสต้องไม่มีที่อยู่อาศัยเป็นของตนเอง ต้องเป็นผู้มีถิ่นที่อยู่ในกรุงโซล หรือมีแผนจะย้ายเข้ากรุงโซลภายใน 1 เดือนหลังจากได้รับสินเชื่อ",
    support_content:
      "สนับสนุนดอกเบี้ยเงินกู้สำหรับที่อยู่อาศัยที่มีเงินประกันการเช่าไม่เกิน 700,000,000 วอน (รวมถึงโอฟิสเทลเพื่อการอยู่อาศัยและที่อยู่อาศัยสวัสดิการผู้สูงอายุ) ในวงเงินไม่เกิน 90% ของเงินประกัน สูงสุด 300,000,000 วอน สนับสนุนได้เพียงครั้งเดียวตลอดชีวิตต่อคู่สมรส 1 คู่ และหากมีคุณสมบัติครบถ้วนสามารถต่ออายุได้สูงสุด 10 ปี",
    application_method: "ตรวจสอบคุณสมบัติผู้มีสิทธิ์ผ่าน Seoul Housing Portal ก่อน จากนั้นไปยื่นขอสินเชื่อที่ธนาคารคู่สัญญา",
    required_documents: [
      "หนังสือรับรองความสัมพันธ์การสมรส (หรือเอกสารรับรองการเป็นคู่ที่จะแต่งงาน)",
      "สัญญาเช่า",
      "เอกสารรับรองรายได้รวมของคู่สมรส",
      "เอกสารยืนยันการไม่มีที่อยู่อาศัยเป็นของตนเอง",
    ],
    checklist: [
      "ตรวจสอบว่ารายได้รวมต่อปีของคู่สมรสไม่เกิน 130,000,000 วอน",
      "ทั้งตนเองและคู่สมรสต้องไม่มีที่อยู่อาศัยเป็นของตนเอง",
      "ตรวจสอบว่าที่อยู่อาศัยมีเงินประกันการเช่าไม่เกิน 700,000,000 วอน",
      "สนับสนุนได้เพียงครั้งเดียวตลอดชีวิต ตรวจสอบว่าเคยได้รับมาก่อนหรือไม่",
    ],
    faq: [
      {
        question: "หากกำลังเตรียมตัวแต่งงานอยู่ สามารถสมัครได้หรือไม่",
        answer: "คู่ที่มีกำหนดจัดพิธีแต่งงานภายใน 6 เดือนนับจากวันที่ยื่นขอสินเชื่อก็สามารถสมัครได้เช่นกัน",
      },
      {
        question: "ตรวจสอบเกณฑ์รายได้ได้อย่างไร",
        answer:
          "ต้องมีรายได้รวมของคู่สมรสต่อปีไม่เกิน 130,000,000 วอน วิธีคำนวณรายได้ที่ถูกต้องควรตรวจสอบผ่านการคำนวณจำลองของเว็บไซต์ Bokjiro หรือสอบถามหน่วยงานที่รับผิดชอบโดยตรงเพื่อความปลอดภัย",
      },
      {
        question: "ตอนสมัครต้องใช้เอกสารอะไรบ้าง",
        answer:
          "ต้องใช้หนังสือรับรองความสัมพันธ์การสมรส (หรือเอกสารรับรองการเป็นคู่ที่จะแต่งงาน) สัญญาเช่า เอกสารรับรองรายได้รวมของคู่สมรส และเอกสารยืนยันการไม่มีที่อยู่อาศัยเป็นของตนเอง เป็นต้น กรุณาตรวจสอบรายการเอกสารที่ถูกต้องอีกครั้งจากประกาศอย่างเป็นทางการก่อนสมัคร",
      },
    ],
  },
