      "ตรวจสอบว่ามีอายุ 24 ปีเต็มในไตรมาสนั้น",
      "ต้องมีคุณสมบัติข้อใดข้อหนึ่ง คือ อาศัยต่อเนื่อง 3 ปี หรืออาศัยรวมกัน 10 ปี",
