  "incheon-postpartum-care-support": {
    title: "การสนับสนุนค่าดูแลหลังคลอด 'มัมเพียนฮัน' เมืองอินชอน",
    summary: "โครงการของเมืองอินชอนที่สนับสนุนค่าดูแลหลังคลอดเป็นเงินตราท้องถิ่นแก่มารดาในกลุ่มเปราะบางที่อาศัยอยู่ในอินชอน",
    eligibility:
      "กลุ่มเป้าหมายคือมารดาในกลุ่มเปราะบาง (ผู้รับสวัสดิการพื้นฐานการดำรงชีพ กลุ่มเกือบยากจน ครอบครัวเลี้ยงเดี่ยว ผู้พิการ ฯลฯ) ที่มีทะเบียนบ้านอยู่ในเมืองอินชอนต่อเนื่องอย่างน้อย 1 ปี ณ วันที่ยื่นคำขอ การผ่านการอบรมผู้ปกครอง (e-learning) ของศูนย์สนับสนุนการเลี้ยงดูบุตรกลางเป็นเงื่อนไขบังคับ",
    support_content:
      "จ่ายเป็นคะแนนเงินตราท้องถิ่น Incheon e-eum จำนวน 1,500,000 วอนต่อมารดา 1 คน นี่คือการสนับสนุนแบบบูรณาการของเมืองอินชอน และอาจมีโครงการสนับสนุนค่าดูแลหลังคลอดเพิ่มเติมแยกต่างหากตามเขตที่อยู่อาศัย",
    application_method: "ยื่นสมัครผ่านศูนย์อนามัยประจำเขตที่พักอาศัย ตั้งแต่สัปดาห์ที่ 32 ของการตั้งครรภ์ จนถึง 90 วันหลังคลอด",
    required_documents: [
      "สมุดบันทึกสุขภาพมารดาหรือใบรับรองการตั้งครรภ์ (กรณียื่นระหว่างตั้งครรภ์)",
      "เอกสารการแจ้งเกิด (กรณียื่นหลังคลอด)",
      "เอกสารรับรองการเป็นกลุ่มเปราะบาง",
      "หนังสือรับรองการผ่านการอบรมผู้ปกครอง",
    ],
    checklist: [
      "ตรวจสอบว่ามีทะเบียนบ้านอยู่ในเมืองอินชอนต่อเนื่องอย่างน้อย 1 ปี ณ วันที่ยื่นคำขอ",
      "ควรผ่านการอบรมผู้ปกครองของศูนย์สนับสนุนการเลี้ยงดูบุตรกลางล่วงหน้า",
      "อย่าพลาดช่วงเวลายื่นคำขอ ตั้งแต่สัปดาห์ที่ 32 ของการตั้งครรภ์ จนถึง 90 วันหลังคลอด",
      "ตรวจสอบโครงการสนับสนุนเพิ่มเติมของศูนย์อนามัยประจำเขตที่พักอาศัยด้วย",
    ],
    faq: [
      {
        question: "หากไม่ใช่กลุ่มเปราะบางจะได้รับหรือไม่",
        answer:
          "การสนับสนุนแบบบูรณาการนี้มีกลุ่มเป้าหมายเป็นมารดาในกลุ่มเปราะบาง เช่น ผู้รับสวัสดิการพื้นฐานการดำรงชีพ กลุ่มเกือบยากจน ครอบครัวเลี้ยงเดี่ยว ผู้พิการ หากไม่เข้าเงื่อนไข กรุณาตรวจสอบโครงการสนับสนุนค่าดูแลหลังคลอดแยกต่างหากของเขตที่พักอาศัย",
      },
      {
        question: "ตรวจสอบเกณฑ์รายได้ได้อย่างไร",
        answer:
          "ต้องมีคุณสมบัติตรงตามเกณฑ์กลุ่มเปราะบาง เช่น ผู้รับสวัสดิการพื้นฐานการดำรงชีพ กลุ่มเกือบยากจน วิธีคำนวณรายได้ที่ถูกต้องควรตรวจสอบผ่านการคำนวณจำลองของเว็บไซต์ Bokjiro หรือสอบถามหน่วยงานที่รับผิดชอบโดยตรงเพื่อความปลอดภัย",
      },
      {
        question: "ตอนสมัครต้องใช้เอกสารอะไรบ้าง",
        answer:
          "ต้องใช้สมุดบันทึกสุขภาพมารดาหรือใบรับรองการตั้งครรภ์ (กรณียื่นระหว่างตั้งครรภ์) เอกสารการแจ้งเกิด (กรณียื่นหลังคลอด) เอกสารรับรองการเป็นกลุ่มเปราะบาง และหนังสือรับรองการผ่านการอบรมผู้ปกครอง กรุณาตรวจสอบรายการเอกสารที่ถูกต้องอีกครั้งจากประกาศอย่างเป็นทางการก่อนสมัคร",
      },
    ],
  },
