    support_content: "สนับสนุนสูงสุดเดือนละ 150,000 วอน เป็นเวลาสูงสุด 6 เดือน (สูงสุด 900,000 วอน) คัดเลือกครึ่งปีแรก 66 คน (ข้อมูลปี 2025)",
    application_method: "สมัครผ่านการประกาศรับสมัคร 2 ครั้งต่อปี ครึ่งปีแรก (กุมภาพันธ์) และครึ่งปีหลัง (สิงหาคม-กันยายน)",
